teams_meeting_default_organizer.source:
def teams_meeting_default_organizer():
    # Client credentials identify the application, not the licensed Microsoft
    # 365 user whose calendar owns the event. Keep that UPN configurable.
    return clean_str(
        os.environ.get('MICROSOFT_TEAMS_ORGANIZER_EMAIL')
        or os.environ.get('MICROSOFT_ORGANIZER_EMAIL')
    )

teams_attendee_emails.source:
def teams_attendee_emails(value):
    if isinstance(value, list):
        candidates = value
    else:
        candidates = re.split(r'[\s,;]+', clean_str(value))
    emails = []
    seen = set()
    for item in candidates:
        email = clean_str(item).lower()
        if not email or email in seen:
            continue
        if not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email):
            raise ValueError(f'Invalid attendee email: {email}')
        seen.add(email)
        emails.append(email)
    return emails

teams_event_recurrence.source:
def teams_event_recurrence(repeat, local_start, occurrences, days_of_week=None):
    if repeat == 'none':
        return None
    start_date = local_start.date().isoformat()
    day_name = local_start.strftime('%A').lower()
    if repeat == 'daily':
        pattern = {'type': 'daily', 'interval': 1}
    elif repeat == 'weekdays':
        pattern = {
            'type': 'weekly',
            'interval': 1,
            'daysOfWeek': ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'],
        }
    else:
        pattern = {'type': 'weekly', 'interval': 1, 'daysOfWeek': list(days_of_week or [day_name])}
    return {
        'pattern': pattern,
        'range': {
            'type': 'numbered',
            'startDate': start_date,
            'numberOfOccurrences': occurrences,
        },
    }

teams_scheduled_occurrence_starts.source:
def teams_scheduled_occurrence_starts(payload):
    """The planned session instants a caller sent, as naive UTC datetimes."""
    supplied = (payload or {}).get('scheduledOccurrences')
    if not isinstance(supplied, list):
        return []
    starts = []
    for item in supplied:
        if not isinstance(item, dict):
            continue
        parsed = parse_graph_datetime(item.get('startDateTimeUtc'))
        if not parsed:
            continue
        if parsed.tzinfo is not None:
            parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
        starts.append(parsed)
    return starts

teams_single_occurrence_payload.source:
def teams_single_occurrence_payload(title, target, attendees, transaction_id=''):
    payload = {
        'subject': title,
        'body': {'contentType': 'HTML', 'content': teams_event_body_html(title)},
        'start': {
            'dateTime': target['start'].replace(second=0, microsecond=0).isoformat(timespec='seconds'),
            'timeZone': 'UTC',
        },
        'end': {
            'dateTime': target['end'].replace(second=0, microsecond=0).isoformat(timespec='seconds'),
            'timeZone': 'UTC',
        },
        'attendees': [
            {'emailAddress': {'address': email, 'name': email.split('@', 1)[0]}, 'type': 'required'}
            for email in attendees
        ],
        'isOnlineMeeting': True,
        'onlineMeetingProvider': 'teamsForBusiness',
        'responseRequested': True,
        'allowNewTimeProposals': True,
        'hideAttendees': True,
    }
    transaction_id = clean_str(transaction_id)[:255]
    if transaction_id:
        payload['transactionId'] = transaction_id
    return payload

teams_calendar_minute_key.source:
def teams_calendar_minute_key(value):
    parsed = value if isinstance(value, datetime) else parse_graph_datetime(value)
    if not parsed:
        return ''
    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
    return parsed.replace(second=0, microsecond=0).isoformat(timespec='minutes')

teams_series_email_list.source:
def teams_series_email_list(*values):
    """The email addresses in a stored invitation list.

    Anything that is not an address is dropped rather than carried through. A
    caller that hands this a JSON *string* it has already exploded into
    characters (``list('["a@b"]')``) would otherwise turn one meeting's roster
    into one "person" per distinct character -- rows that reach Graph as
    invitees and the attendance panel as "28 expected".
    """
    emails = []
    for value in values:
        if isinstance(value, str):
            candidates = parse_json_value(value, [])
            if not isinstance(candidates, list):
                candidates = re.split(r'[\s,;]+', value)
        elif isinstance(value, (list, tuple, set)):
            candidates = value
        else:
            candidates = []
        for candidate in candidates:
            email = clean_str(candidate).lower()
            if not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email):
                continue
            if email not in emails:
                emails.append(email)
    return emails

teams_online_meeting_owner_id.source:
def teams_online_meeting_owner_id(organizer, join_url=''):
    """Return the organizer object ID required by onlineMeetings Graph routes."""
    configured_id = clean_str(os.environ.get('MICROSOFT_TEAMS_ORGANIZER_ID'))
    configured_organizer = teams_meeting_default_organizer()
    organizer_matches_default = (
        configured_organizer
        and clean_str(organizer).lower() == configured_organizer.lower()
    )
    if re.fullmatch(r'[0-9a-fA-F-]{36}', configured_id) and organizer_matches_default:
        return configured_id
    try:
        decoded_url = urllib_parse.unquote(clean_str(join_url))
        context_values = urllib_parse.parse_qs(urlparse(decoded_url).query).get('context') or []
        if context_values:
            context = json.loads(urllib_parse.unquote(context_values[0]))
            organizer_id = clean_str(context.get('Oid') or context.get('oid'))
            if re.fullmatch(r'[0-9a-fA-F-]{36}', organizer_id):
                return organizer_id
    except (TypeError, ValueError, json.JSONDecodeError):
        pass
    return clean_str(organizer)

teams_online_meeting_from_join_url.source:
def teams_online_meeting_from_join_url(organizer, join_url):
    """Find the onlineMeeting behind a calendar event when permissions allow."""
    if not join_url:
        return {}
    escaped_url = join_url.replace("'", "''")
    query = urllib_parse.urlencode({'$filter': f"joinWebUrl eq '{escaped_url}'"})
    owner_key = urllib_parse.quote(teams_online_meeting_owner_id(organizer, join_url), safe='')
    from coach_api.views import microsoft_graph_request
    response = microsoft_graph_request('GET', f'users/{owner_key}/onlineMeetings?{query}')
    values = response.get('value') if isinstance(response, dict) else []
    return values[0] if values else {}

graph_timezone_iana.source:
def graph_timezone_iana(graph_settings):
    """IANA id for the calendar's timezone, for the wizard to schedule against."""
    if graph_settings.get('_schedule_timezone_iana'):
        return graph_settings['_schedule_timezone_iana']
    override = clean_str(os.environ.get('MICROSOFT_GRAPH_TIMEZONE_IANA'))
    if override:
        return override
    return calendar_zone(clean_str(graph_settings.get('timezone')) or 'Europe/London').key

teams_schedule_settings.source:
def teams_schedule_settings(graph_settings, payload=None, series=None):
    """A new calendar's chosen clock, or an existing calendar's saved clock."""
    selected = clean_str((payload or {}).get('scheduleTimeZone'))
    if selected and selected not in ('Africa/Cairo', 'Europe/London'):
        raise ValueError('Choose Egypt or England as the schedule time zone.')
    stored = clean_str((series or {}).get('timezone'))
    zone = calendar_zone(stored).key if stored else selected
    if not zone:
        return graph_settings
    windows = next((key for key, value in GRAPH_WINDOWS_TO_IANA.items() if value == zone), zone)
    return {**graph_settings, 'timezone': windows, '_schedule_timezone_iana': zone}

teams_shifted_occurrence_targets.source:
def teams_shifted_occurrence_targets(payload, default_duration):
    """Wizard dates the calendar occurrences must land on, holiday shifts included."""
    supplied = payload.get('scheduledOccurrences')
    if not isinstance(supplied, list) or len(supplied) <= 1:
        return []
    targets = []
    for index, item in enumerate(supplied):
        if not isinstance(item, dict):
            continue
        start = parse_graph_datetime(item.get('startDateTimeUtc'))
        if not start:
            continue
        try:
            item_duration = max(15, min(1440, int(item.get('durationMinutes') or default_duration)))
        except (TypeError, ValueError):
            item_duration = default_duration
        try:
            session_number = max(1, int(item.get('sessionNumber') or index + 1))
        except (TypeError, ValueError):
            session_number = index + 1
        targets.append({
            'session_number': session_number,
            'start': start,
            'end': start + timedelta(minutes=item_duration),
        })
    return targets

publish_teams_calendar_attendees.source:
def publish_teams_calendar_attendees(
    request, owner_key, event, attendees, occurrence_details=None, *, force=False,
    title='', silent=False, dates_unchanged=False,
):
    """Publish the final invitation list to the master and restored sessions.

    ``silent`` decides only whether Microsoft is asked to announce the write, not
    who is on the meeting. Who belongs to a calendar event and whether an email
    goes out are separate questions, and an author who chose not to email must
    still end up with every intended learner invited -- the alternative, a
    session nobody is on, is a silence bought by breaking the meeting.

    A silent publish also keeps to the narrower ``attendees``-only patch, which
    is the shape Microsoft documents as touching only the people who changed,
    and it is skipped when the list already matches -- nothing to write is
    nothing for Microsoft to send. A publish that is meant to be heard writes
    either way: a session restored silently already carries its people, and
    Microsoft puts a meeting on their calendars only when something is sent.
    """
    headers = GRAPH_SILENT_INVITE_HEADERS if silent else None
    announce = not silent
    def needs_force_patch(current):
        return (
            not dates_unchanged
            or not attendees_already_match(attendees, current.get('attendees'), event_organizer_address(current))
            or clean_str(title) and clean_str(title) != clean_str(current.get('subject'))
            or current.get('hideAttendees') is not True
        )

    if force:
        if announce:
            # Whoever this announced write drops is taken off silently first, so
            # Exchange sends them no cancellation; the people who stay still hear.
            event, _removed = remove_attendees_silently(request, owner_key, event, attendees)
        if needs_force_patch(event):
            request(
                'PATCH',
                f'users/{owner_key}/events/{urllib_parse.quote(clean_str(event.get("id")), safe="")}',
                payload={
                    'subject': clean_str(title) or clean_str(event.get('subject')),
                    'hideAttendees': True,
                    'attendees': attendees,
                },
                extra_headers=headers,
            )
    else:
        publish_attendees(request, owner_key, event, attendees, extra_headers=headers, always=announce)
    for detail in occurrence_details or []:
        event_id = clean_str(detail.get('graph_event_id'))
        if not event_id or event_id == clean_str(event.get('id')):
            continue
        standalone = request(
            'GET', f'users/{owner_key}/events/{urllib_parse.quote(event_id, safe="")}',
        )
        if force:
            if announce:
                standalone, _removed = remove_attendees_silently(request, owner_key, standalone, attendees)
            if needs_force_patch(standalone):
                request(
                    'PATCH',
                    f'users/{owner_key}/events/{urllib_parse.quote(event_id, safe="")}',
                    payload={
                        'subject': clean_str(title) or clean_str(standalone.get('subject')),
                        'hideAttendees': True,
                        'attendees': attendees,
                    },
                    extra_headers=headers,
                )
        else:
            publish_attendees(request, owner_key, standalone, attendees, extra_headers=headers, always=announce)

forward_teams_invitation.source:
def forward_teams_invitation(request, owner_key, event_ids, recipients, comment=''):
    """Microsoft forwarding is disabled; optional email is sent by the LMS.

    This prevents explicit /forward calls. It does not certify suppression of
    the messages Exchange may generate from an event PATCH.
    """
    if not recipients:
        return []
    return [{'code': 'teams_calendar_mail_disabled',
             'message': 'No Microsoft invitation was requested. Use the LMS email option if you want to email the people added.'}]

persist_recreated_occurrence_details.source:
def persist_recreated_occurrence_details(live_session_id, recreated_details):
    """Point a moved session at the event and meeting Teams actually gave it.

    A recreated occurrence is its own event with its own Teams link and its own
    online meeting, so the series link and meeting ID are the wrong answer for
    it: learners would join a session that no longer exists, and its transcript,
    recording and attendance would be looked for under a meeting that never ran.
    """
    if not recreated_details:
        return
    now = datetime.utcnow()
    for detail in recreated_details:
        try:
            session_number = int(detail.get('session_number') or 0)
        except (TypeError, ValueError):
            continue
        if session_number <= 0:
            continue
        update = {}
        for column in ('graph_event_id', 'join_url', 'online_meeting_id'):
            value = clean_str(detail.get(column))
            if value:
                update[column] = value
        if not update:
            continue
        update['updated_at'] = now
        update_authoring_rows(
            LIVE_SESSION_OCCURRENCES_TABLE,
            'live_session_id = %s and session_number = %s',
            [live_session_id, session_number],
            update,
        )

closest_live_occurrence.source:
def closest_live_occurrence(occurrences, timestamp):
    if not occurrences or not timestamp:
        return None
    comparable_timestamp = timestamp.replace(tzinfo=None)

    def distance(row):
        scheduled = row.get('scheduled_start') or timestamp
        return abs((scheduled.replace(tzinfo=None) - comparable_timestamp).total_seconds())

    return min(
        occurrences,
        key=distance,
    )

