        rows = authoring_fetch_all(
            AUTHORING_MODULES_TABLE,
            'module_catalogue_id = %s',
            [module_id],
        )
        saved_title = clean_str(rows[0].get('title')) if rows else ''
        if saved_title:
            return saved_title
