def teams_online_meeting_owner_id(organizer, join_url=''):
    """Return the organizer object ID required by onlineMeetings Graph routes."""
    configured_id = clean_str(os.environ.get('MICROSOFT_TEAMS_ORGANIZER_ID'))
    configured_organizer = teams_meeting_default_organizer()
    organizer_matches_default = (
        configured_organizer
        and clean_str(organizer).lower() == configured_organizer.lower()
    )
    if re.fullmatch(r'[0-9a-fA-F-]{36}', configured_id) and organizer_matches_default:
        return configured_id
    try:
        decoded_url = urllib_parse.unquote(clean_str(join_url))
        context_values = urllib_parse.parse_qs(urlparse(decoded_url).query).get('context') or []
        if context_values:
            context = json.loads(urllib_parse.unquote(context_values[0]))
            organizer_id = clean_str(context.get('Oid') or context.get('oid'))
            if re.fullmatch(r'[0-9a-fA-F-]{36}', organizer_id):
                return organizer_id
    except (TypeError, ValueError, json.JSONDecodeError):
        pass
    return clean_str(organizer)
def teams_online_meeting_from_join_url(organizer, join_url):
    """Find the onlineMeeting behind a calendar event when permissions allow."""
    if not join_url:
        return {}
    escaped_url = join_url.replace("'", "''")
    query = urllib_parse.urlencode({'$filter': f"joinWebUrl eq '{escaped_url}'"})
    owner_key = urllib_parse.quote(teams_online_meeting_owner_id(organizer, join_url), safe='')
    from coach_api.views import microsoft_graph_request
    response = microsoft_graph_request('GET', f'users/{owner_key}/onlineMeetings?{query}')
    values = response.get('value') if isinstance(response, dict) else []
    return values[0] if values else {}
def graph_timezone_iana(graph_settings):
    """IANA id for the calendar's timezone, for the wizard to schedule against."""
    if graph_settings.get('_schedule_timezone_iana'):
        return graph_settings['_schedule_timezone_iana']
    override = clean_str(os.environ.get('MICROSOFT_GRAPH_TIMEZONE_IANA'))
    if override:
        return override
    return calendar_zone(clean_str(graph_settings.get('timezone')) or 'Europe/London').key
def teams_schedule_settings(graph_settings, payload=None, series=None):
    """A new calendar's chosen clock, or an existing calendar's saved clock."""
    selected = clean_str((payload or {}).get('scheduleTimeZone'))
    if selected and selected not in ('Africa/Cairo', 'Europe/London'):
        raise ValueError('Choose Egypt or England as the schedule time zone.')
    stored = clean_str((series or {}).get('timezone'))
    zone = calendar_zone(stored).key if stored else selected
    if not zone:
        return graph_settings
    windows = next((key for key, value in GRAPH_WINDOWS_TO_IANA.items() if value == zone), zone)
    return {**graph_settings, 'timezone': windows, '_schedule_timezone_iana': zone}
def teams_shifted_occurrence_targets(payload, default_duration):
    """Wizard dates the calendar occurrences must land on, holiday shifts included."""
    supplied = payload.get('scheduledOccurrences')
    if not isinstance(supplied, list) or len(supplied) <= 1:
        return []
    targets = []
    for index, item in enumerate(supplied):
        if not isinstance(item, dict):
            continue
        start = parse_graph_datetime(item.get('startDateTimeUtc'))
        if not start:
            continue
        try:
            item_duration = max(15, min(1440, int(item.get('durationMinutes') or default_duration)))
        except (TypeError, ValueError):
            item_duration = default_duration
        try:
            session_number = max(1, int(item.get('sessionNumber') or index + 1))
        except (TypeError, ValueError):
            session_number = index + 1
        targets.append({
            'session_number': session_number,
            'start': start,
            'end': start + timedelta(minutes=item_duration),
        })
    return targets
def teams_expanded_instances(owner_key, event_key, instance_query, expected, deadline_seconds=15.0):
    """The series' occurrences, waited for until Microsoft has expanded them.

    Extending a recurrence is not atomic on Microsoft's side. The PATCH that
    raises a four-session series to ten answers straight away, but the very next
    read of ``/instances`` can still list only the four that existed before.
    Reconciling against that answer leaves every added session un-shifted, and
    the verification that follows then names the first added session as missing
    -- so an author who adds sessions to a calendar that already exists is told
    the update failed while Microsoft is still applying it, and the retry runs
    the whole path again. Re-read until the planned number of occurrences is
    there. A series that really is short costs the deadline once instead of
    reporting a mismatch that is not one.
    """
    from coach_api.views import microsoft_graph_request

    instances, waited = [], 0.0
    while True:
        response = microsoft_graph_request('GET', f'users/{owner_key}/events/{event_key}/instances?{instance_query}')
        instances = [graph_event_utc(item) for item in (response.get('value') or [])] if isinstance(response, dict) else []
        if len(instances) >= expected or waited >= deadline_seconds:
            return sorted(instances, key=lambda item: clean_str((item.get('start') or {}).get('dateTime')))
        time.sleep(2.0)
        waited += 2.0
def vacated_occurrence_keys(targets, existing_occurrences):
    """The dates sessions in THIS operation have just moved off.

    Keyed by the minute key of the old date, holding the identity that proves
    it: the LMS session number, where that session was, and where it is going.
    One entry per session whose stored date differs from the date it is being
    given now -- that old slot is the stale twin of a session still on this
    calendar, and the only occurrence a shift is ever allowed to retire.

    A session absent from ``targets`` contributes nothing. Its date has not been
    vacated; it is simply not part of this send. That distinction is the whole
    point: ``scheduledOccurrences`` is a positive update list, not a desired
    state, so "this Microsoft date is not in the array" says nothing about
    whether anybody wanted it cancelled -- and a week routed to its own
    additional meeting, or a weekly slot Graph materialised from the unbroken
    recurrence, is absent for reasons that have nothing to do with intent.
    """
    stored = {}
    for row in existing_occurrences or ():
        number = parse_int((row or {}).get('session_number'))
        key = teams_calendar_minute_key((row or {}).get('scheduled_start'))
        if number and key:
            stored[number] = key
    vacated = {}
    for target in targets or ():
        number = parse_int((target or {}).get('session_number'))
        previous = stored.get(number)
        current = teams_calendar_minute_key((target or {}).get('start'))
        if number and previous and current and previous != current:
            vacated[previous] = {
                'session_number': number,
                'previous_start': previous,
                'new_start': current,
                'reason': 'stale_twin_of_moved_session',
            }
    return vacated
def tracked_occurrence_keys(existing_occurrences):
    """Every date this calendar still owns a live session on.

    A Graph weekly recurrence materialises an instance in EVERY weekly slot of
    its range, so most of what Microsoft lists was never a session anybody
    planned -- it is filler the pattern generated, and clearing it is the only
    way a holiday-shifted plan can match at all.

    These keys are what tells the two apart. A date with an LMS occurrence row
    behind it is a real session, and a real session is never retired because it
    is absent from a send list: that is how a week routed to its own additional
    meeting came to be cancelled. A date with no row behind it never was one.
    """
    return {
        key for key in (
            teams_calendar_minute_key((row or {}).get('scheduled_start'))
            for row in existing_occurrences or ()
        ) if key
    }
def flag_teams_occurrence_leftovers(
    deletions, *, live_session_id='', module_catalogue_id='', source='holiday_move_cleanup',
):
    """Report the Teams slots a save no longer wants. Never removes them.

    These used to be deleted here: the weekly filler a recurrence generates in a
    gap, and the slot a session moved off. Exchange answers every organizer
    delete with a "Canceled: <module>" email to everyone invited, so a week
    handed to its own additional meeting, or a session added after a gap, had the
    whole cohort told a session was cancelled that nobody had cancelled.

    No save, sync or background job cancels anything now. A slot that is no
    longer part of the plan is left exactly where it is on Teams and returned
    here, so the screen can say so; the only way it leaves Microsoft is the
    explicit Cancel on that slot (``teams_calendar_actions`` scope 'leftover').
    """
    leftovers = []
    for deletion in deletions or ():
        instance_id = clean_str((deletion or {}).get('instance_id'))
        if not instance_id:
            continue
        logger.info(
            'Teams occurrence left for manual review: live_session_id=%s module_catalogue_id=%s graph_event_id=%s '
            'session_number=%s previous_start=%s new_start=%s reason=%s source=%s',
            live_session_id, module_catalogue_id, instance_id,
            deletion.get('session_number'), deletion.get('previous_start'),
            deletion.get('new_start'), deletion.get('reason'), source,
        )
        leftovers.append({
            'eventId': instance_id,
            'startDateTimeUtc': f"{clean_str(deletion.get('previous_start'))}:00Z" if clean_str(deletion.get('previous_start')) else '',
            'sessionNumber': deletion.get('session_number') or None,
            'reason': clean_str(deletion.get('reason')),
        })
    return leftovers
def verify_teams_calendar_with_standalones(
    request, owner_key, event_id, targets, expected_join_url='', recurring=True,
    occurrence_details=None, expected_attendees=None,
):
    """Verify the master series and any deleted occurrences restored separately.

    ``expected_attendees`` is checked against each separately restored session.
    Dates alone used to be the whole of "verified", so a session rebuilt on its
    own event with an empty invitation list passed every check and the update
    reported success -- while nobody but the organizer had that session. An
    occurrence is only really restored once the people it is for are on it.
    """
    details_by_number = {
        int(detail.get('session_number') or 0): detail
        for detail in (occurrence_details or [])
        if clean_str(detail.get('graph_event_id'))
        and clean_str(detail.get('graph_event_id')) != clean_str(event_id)
    }
    master_targets = [
        target for target in targets
        if int(target['session_number']) not in details_by_number
    ]
    if not master_targets:
        raise CalendarMismatch('The recurring Teams calendar has no verified series occurrences.')
    event = verify_calendar(
        request, owner_key, event_id, master_targets, expected_join_url, recurring,
    )
    for target in targets:
        detail = details_by_number.get(int(target['session_number']))
        if not detail:
            continue
        standalone = verify_calendar(
            request,
            owner_key,
            clean_str(detail.get('graph_event_id')),
            [target],
            clean_str(detail.get('join_url')),
            False,
        )
        if expected_attendees is None:
            continue
        # The same comparison ``publish_attendees`` confirms a published list
        # with: a session carrying someone the series does not invite is as wrong
        # as one missing a learner, and neither is left standing as "verified" --
        # while an alias Microsoft stored under its primary address, and the
        # organizer of the session itself, are the same people either way.
        missing, extra = attendee_differences(
            expected_attendees, standalone.get('attendees'), event_organizer_address(standalone),
        )
        if missing or extra:
            raise CalendarMismatch(
                f"Session {target['session_number']} was restored on its own Teams event "
                f'without its invited people ({unconfirmed_attendee_detail(missing, extra)}). '
                'The calendar was not confirmed.'
            )
    return event
def publish_teams_calendar_attendees(
    request, owner_key, event, attendees, occurrence_details=None, *, force=False,
    title='', silent=False, dates_unchanged=False,
):
    """Publish the final invitation list to the master and restored sessions.

    ``silent`` decides only whether Microsoft is asked to announce the write, not
    who is on the meeting. Who belongs to a calendar event and whether an email
    goes out are separate questions, and an author who chose not to email must
    still end up with every intended learner invited -- the alternative, a
    session nobody is on, is a silence bought by breaking the meeting.

    A silent publish also keeps to the narrower ``attendees``-only patch, which
    is the shape Microsoft documents as touching only the people who changed,
    and it is skipped when the list already matches -- nothing to write is
    nothing for Microsoft to send. A publish that is meant to be heard writes
    either way: a session restored silently already carries its people, and
    Microsoft puts a meeting on their calendars only when something is sent.
    """
    headers = GRAPH_SILENT_INVITE_HEADERS if silent else None
    announce = not silent
    def needs_force_patch(current):
        return (
            not dates_unchanged
            or not attendees_already_match(attendees, current.get('attendees'), event_organizer_address(current))
            or clean_str(title) and clean_str(title) != clean_str(current.get('subject'))
            or current.get('hideAttendees') is not True
        )

    if force:
        if announce:
            # Whoever this announced write drops is taken off silently first, so
            # Exchange sends them no cancellation; the people who stay still hear.
            event, _removed = remove_attendees_silently(request, owner_key, event, attendees)
        if needs_force_patch(event):
            request(
                'PATCH',
                f'users/{owner_key}/events/{urllib_parse.quote(clean_str(event.get("id")), safe="")}',
                payload={
                    'subject': clean_str(title) or clean_str(event.get('subject')),
                    'hideAttendees': True,
                    'attendees': attendees,
                },
                extra_headers=headers,
            )
    else:
        publish_attendees(request, owner_key, event, attendees, extra_headers=headers, always=announce)
    for detail in occurrence_details or []:
        event_id = clean_str(detail.get('graph_event_id'))
        if not event_id or event_id == clean_str(event.get('id')):
            continue
        standalone = request(
            'GET', f'users/{owner_key}/events/{urllib_parse.quote(event_id, safe="")}',
        )
        if force:
            if announce:
                standalone, _removed = remove_attendees_silently(request, owner_key, standalone, attendees)
            if needs_force_patch(standalone):
                request(
                    'PATCH',
                    f'users/{owner_key}/events/{urllib_parse.quote(event_id, safe="")}',
                    payload={
                        'subject': clean_str(title) or clean_str(standalone.get('subject')),
                        'hideAttendees': True,
                        'attendees': attendees,
                    },
                    extra_headers=headers,
                )
        else:
            publish_attendees(request, owner_key, standalone, attendees, extra_headers=headers, always=announce)
def teams_newly_invited(stored, invited):
    """Who a save adds to a meeting that already exists.

    Compared case-insensitively against the roster the calendar holds now, so
    moving someone between attendee, presenter and co-organizer does not make
    them new. Order and spelling come from the incoming list.
    """
    was = {clean_str(email).lower() for email in (stored or []) if clean_str(email)}
    added, seen = [], set()
    for email in invited or []:
        key = clean_str(email).lower()
        if not key or key in was or key in seen:
            continue
        seen.add(key)
        added.append(clean_str(email))
    return added
def forward_teams_invitation(request, owner_key, event_ids, recipients, comment=''):
    """Microsoft forwarding is disabled; optional email is sent by the LMS.

    This prevents explicit /forward calls. It does not certify suppression of
    the messages Exchange may generate from an event PATCH.
    """
    if not recipients:
        return []
    return [{'code': 'teams_calendar_mail_disabled',
             'message': 'No Microsoft invitation was requested. Use the LMS email option if you want to email the people added.'}]
def reschedule_single_live_session_occurrence(
    series, occurrence, new_start_utc, duration, *, notify_attendees=False,
):
    """Move one session of a live-session series to a new instant via Graph.

    The module schedule sets every session's time; this is the escape hatch for
    the single session that has to differ. A plain recurring series shares one
    event, so the session is one of its instances and Graph is asked to move that
    instance -- it becomes an exception, leaving every other session, and the
    module's default time, exactly where they were. A session that already had to
    be recreated on its own event (a holiday shift) is moved directly. Mirrors
    ``apply_teams_occurrence_shifts`` for the one-instance case, including its
    fall back to recreating the occurrence when Graph refuses to move it across
    the recurrence boundary. The module always keeps its shared join URL; if
    Graph refuses the move, the occurrence is left unchanged and a warning is
    returned. Returns ``(join_url, online_meeting_id, event_id, warnings)``.
    """
    from coach_api.views import microsoft_graph_request

    warnings = []
    organizer = clean_str(series.get('organizer_email')) or teams_meeting_default_organizer()
    owner_key = urllib_parse.quote(organizer, safe='')
    series_event_id = clean_str(series.get('graph_event_id'))
    occ_event_id = clean_str(occurrence.get('graph_event_id'))
    new_end_utc = new_start_utc + timedelta(minutes=duration)
    title = clean_str(series.get('module_title') or 'Live session')
    join_url = clean_str(occurrence.get('join_url')) or clean_str(series.get('join_url'))
    online_meeting_id = clean_str(occurrence.get('online_meeting_id'))
    result_event_id = occ_event_id or series_event_id
    patch_body = {
        'start': {'dateTime': new_start_utc.replace(second=0, microsecond=0).isoformat(timespec='seconds'), 'timeZone': 'UTC'},
        'end': {'dateTime': new_end_utc.replace(second=0, microsecond=0).isoformat(timespec='seconds'), 'timeZone': 'UTC'},
        'hideAttendees': True,
    }

    def move_verified(instance_id):
        path = f'users/{owner_key}/events/{urllib_parse.quote(instance_id, safe="")}'
        current = microsoft_graph_request('GET', path)
        actual_link = clean_str((current.get('onlineMeeting') or {}).get('joinUrl'))
        if current.get('isCancelled') or actual_link != join_url or not safe_teams_join_url(actual_link):
            raise RuntimeError('The session join link or calendar identity could not be verified.')
        microsoft_graph_request(
            'PATCH', path, payload=patch_body,
            extra_headers=None if notify_attendees else GRAPH_SILENT_INVITE_HEADERS,
        )
        verify_calendar(microsoft_graph_request, owner_key, instance_id, [
            {'session_number': occurrence.get('session_number') or 1,
             'start': utc_datetime(new_start_utc), 'end': utc_datetime(new_end_utc)},
        ], join_url, False)

    # Already its own event: move it directly, no series instance to resolve.
    if occ_event_id and occ_event_id != series_event_id:
        try:
            move_verified(occ_event_id)
        except RuntimeError as exc:
            logger.warning('Unable to reschedule a standalone Teams occurrence: %s', exc)
            warnings.append({'code': 'teams_occurrence_not_moved', 'message': 'Microsoft Teams could not move this session.', 'detail': str(exc)})
        return join_url, online_meeting_id, result_event_id, warnings

    if not series_event_id:
        warnings.append({'code': 'teams_occurrence_missing_event', 'message': 'This session has no calendar event to move.', 'detail': ''})
        return join_url, online_meeting_id, result_event_id, warnings

    # One of the recurring series' instances: find the one sitting on the current
    # start and move it. Widen the window enough to survive a DST shift of the
    # stored instant either side of the day.
    current_start = parse_graph_datetime(occurrence.get('scheduled_start'))
    pivot = current_start or new_start_utc
    instance_query = urllib_parse.urlencode({
        'startDateTime': (pivot - timedelta(days=2)).isoformat(),
        'endDateTime': (pivot + timedelta(days=2)).isoformat(),
        '$top': 50,
    })
    event_key = urllib_parse.quote(series_event_id, safe='')
    try:
        response = microsoft_graph_request('GET', f'users/{owner_key}/events/{event_key}/instances?{instance_query}')
        instances = response.get('value') if isinstance(response, dict) else []
    except RuntimeError as exc:
        logger.warning('Unable to list Teams series instances to reschedule one session: %s', exc)
        warnings.append({'code': 'teams_occurrence_not_moved', 'message': 'Microsoft Teams could not find this session to move.', 'detail': str(exc)})
        return join_url, online_meeting_id, result_event_id, warnings

    current_key = teams_calendar_minute_key(current_start) if current_start else ''
    instance = next(
        (item for item in instances if current_key and teams_calendar_minute_key((item.get('start') or {}).get('dateTime')) == current_key),
        None,
    )
    # A single-instance window that returned exactly one candidate is that
    # session even when the stored minute drifted (DST); anything ambiguous is
    # left untouched rather than guessed.
    if instance is None and len(instances) == 1:
        instance = instances[0]
    instance_id = clean_str((instance or {}).get('id'))
    if not instance_id:
        warnings.append({'code': 'teams_occurrence_not_found', 'message': 'Microsoft Teams did not list this session, so it was not moved.', 'detail': ''})
        return join_url, online_meeting_id, result_event_id, warnings

    try:
        move_verified(instance_id)
    except RuntimeError as exc:
        warnings.append({
            'code': 'teams_occurrence_not_moved',
            'message': 'Microsoft Teams could not move this occurrence, so it was left in the recurring series to preserve the module\'s fixed join URL.',
            'detail': str(exc),
        })
    return join_url, online_meeting_id, instance_id, warnings
def teams_meeting_base_path(organizer, meeting_id, join_url=''):
    """Graph path of one onlineMeeting, resolved for the organizer that owns it."""
    owner_key = urllib_parse.quote(teams_online_meeting_owner_id(organizer, join_url), safe='')
    return f'users/{owner_key}/onlineMeetings/{urllib_parse.quote(clean_str(meeting_id), safe="")}'
def teams_warning_sentence(warnings):
    """Graph's own reasons for a refusal, as one sentence an author can act on.

    Every warning raised on the Teams paths carries a ``message`` saying what
    was not applied and a ``detail`` holding Microsoft's raw error. Both are
    wanted: the message is what the person reads, the detail is the code
    support asks for. Duplicates are collapsed -- one policy refusal arrives
    once per occurrence on a shifted series, and ten copies of a sentence reads
    as ten separate faults.
    """
    seen, parts = set(), []
    for warning in warnings or ():
        if not isinstance(warning, dict):
            text = clean_str(warning)
        else:
            message = clean_str(warning.get('message'))
            detail = clean_str(warning.get('detail'))
            text = f'{message} ({detail})' if message and detail else message or detail
        if text and text not in seen:
            seen.add(text)
            parts.append(text)
    return ' '.join(parts)
def apply_teams_meeting_options(
    organizer,
    join_url,
    recording='none',
    lobby_bypass='invited',
    spoken_language='en-GB',
    attendees=(),
    presenters=(),
    co_organizers=(),
    online_meeting_id='',
    meeting=None,
    groups=None,
    live_session_id='',
):
    """Apply this deployment's meeting policy to the onlineMeeting behind an event.

    Every Teams meeting the LMS owns comes through here: a module's series, a
    rescheduled one, a holiday-shifted session recreated on its own event, and a
    coach's booking alike. A calendar event only ever creates the meeting at the
    tenant defaults, so recording, automatic recording, transcription, the lobby
    and who presents exist only once this has run against it -- a meeting that
    skips it opens with nothing recording, no transcript afterwards, and every
    guest a presenter.

    ``groups`` limits the PATCH to the option groups that need sending (see
    teams_meeting_options_policy); None sends all of them, as every caller
    creating a meeting does. An empty set sends nothing and reports applied.

    Returns ``(applied, meeting, warnings)`` and never raises. The calendar
    invitation is real work already done, and these options need
    OnlineMeetings.ReadWrite.All plus an application access policy on the
    organizer that a deployment may not have granted yet. Every refusal is
    kept by teams_graph_failure_log (``live_session_id`` names the series).
    """
    from coach_api.views import microsoft_graph_request
    from .teams_graph_failure_log import OPTIONS_PATCH, OPTIONS_RESOLVE, record_graph_failure
    from .teams_meeting_options_policy import ALL_GROUPS, graph_error_details, meeting_options_patch

    groups = set(ALL_GROUPS) if groups is None else set(groups)
    resolved = meeting if isinstance(meeting, dict) else {}
    if not groups:
        # Nothing about how this meeting runs changed: no Graph call at all.
        return True, resolved, []
    meeting_id = clean_str(online_meeting_id) or clean_str(resolved.get('id'))
    if not meeting_id and join_url:
        try:
            resolved = teams_online_meeting_from_join_url(organizer, join_url) or {}
        except RuntimeError as exc:
            logger.warning('Unable to resolve the onlineMeeting behind a Teams event: %s', exc)
            record_graph_failure(OPTIONS_RESOLVE, str(exc), live_session_id=live_session_id, organizer=organizer,
                                 organizer_object_id=teams_online_meeting_owner_id(organizer, join_url),
                                 groups=groups)
            return False, resolved, [{
                'code': 'teams_meeting_options_not_applied',
                'message': (
                    'The Teams link was created and saved, but Microsoft has not exposed its meeting options yet. '
                    'Recording, transcription and lobby settings remain pending; open the calendar review to retry.'
                ),
                # The raw Graph refusal is kept in teams_graph_failures for
                # diagnosis. It is not shown as a permissions verdict here:
                # Graph can return the same 403 briefly after creating an event.
                'detail': '',
            }]
        meeting_id = clean_str(resolved.get('id'))
    if not meeting_id:
        return False, resolved, [{
            'code': 'teams_meeting_options_not_applied',
            'message': (
                'Microsoft Graph has not exposed this meeting: its online meeting ID is not available yet, so the '
                'recording, transcription and lobby options were not applied.'
            ),
            'detail': '',
        }]

    lobby_choice = clean_str(lobby_bypass).lower() or 'invited'
    if lobby_choice not in TEAMS_LOBBY_VALUES:
        lobby_choice = 'invited'
    # Never `list(...)` these: a caller that passes the stored JSON text instead
    # of a parsed list would have it split into characters here.
    patch = meeting_options_patch(
        groups, recording=recording, lobby_scope=TEAMS_LOBBY_VALUES[lobby_choice],
        spoken_language=spoken_language, attendees=teams_series_email_list(attendees),
        presenters=teams_series_email_list(presenters), co_organizers=teams_series_email_list(co_organizers),
    )
    if not patch:
        return True, resolved, []
    meeting_path = teams_meeting_base_path(organizer, meeting_id, join_url)
    organizer_object_id = teams_online_meeting_owner_id(organizer, join_url)
    try:
        microsoft_graph_request(
            'PATCH',
            meeting_path,
            payload=patch,
        )
    except RuntimeError as exc:
        from coach_api.views import get_graph_settings
        graph_settings = get_graph_settings()
        logger.warning(
            'Unable to apply Teams meeting options: organizer_upn=%s '
            'organizer_object_id=%s graph_client_id=%s method=PATCH path=%s '
            'online_meeting_id=%s error=%s',
            organizer,
            organizer_object_id,
            graph_settings.get('client_id', ''),
            meeting_path,
            meeting_id,
            exc,
        )
        record_graph_failure(OPTIONS_PATCH, str(exc), live_session_id=live_session_id, online_meeting_id=meeting_id,
                             organizer=organizer, organizer_object_id=organizer_object_id, groups=groups)
        return False, resolved, [{
            'code': 'teams_meeting_options_not_applied',
            'message': (
                'The Teams meeting exists, but Microsoft Graph did not apply its lobby, recording, transcription '
                'and presenter options. Check the Graph error detail for the exact cause.'
            ),
            'detail': str(exc),
            'groups': sorted(groups),
            'graphError': graph_error_details(str(exc)),
            'organizer': clean_str(organizer),
            'organizerObjectId': organizer_object_id,
            'failureLogged': True,
        }]
    return True, resolved, []
def teams_standalone_occurrence_meeting(owner_key, event, target, invited_people, meeting_options, groups=None):
    """Give an occurrence recreated on its own event the options its series has.

    Graph builds a fresh onlineMeeting for a fresh event, at the tenant defaults,
    and the series own options never reach it. Left alone, the one session that
    had to move is the one that records nothing and produces no transcript.
    """
    from coach_api.views import microsoft_graph_request

    warnings = []
    event_id = clean_str((event or {}).get('id'))
    join_url = clean_str(((event or {}).get('onlineMeeting') or {}).get('joinUrl'))
    if event_id and not join_url:
        try:
            refreshed = microsoft_graph_request(
                'GET',
                f'users/{owner_key}/events/{urllib_parse.quote(event_id, safe="")}',
            )
            join_url = clean_str(((refreshed or {}).get('onlineMeeting') or {}).get('joinUrl'))
        except RuntimeError as exc:
            logger.warning('Unable to read the Teams link of a recreated occurrence: %s', exc)
    options = meeting_options or {}
    online_meeting_id = ''
    if join_url and options:
        _applied, meeting, option_warnings = apply_teams_meeting_options(
            options.get('organizer', ''),
            join_url,
            recording=options.get('recording', 'none'),
            lobby_bypass=options.get('lobby_bypass', 'invited'),
            spoken_language=options.get('spoken_language', 'en-GB'),
            attendees=invited_people,
            presenters=options.get('presenters') or [],
            co_organizers=options.get('co_organizers') or [],
            groups=groups,
        )
        warnings.extend(option_warnings)
        online_meeting_id = clean_str((meeting or {}).get('id'))
    return {
        'session_number': (target or {}).get('session_number'),
        'graph_event_id': event_id,
        'join_url': join_url,
        'online_meeting_id': online_meeting_id,
        'warnings': warnings,
    }
def refresh_standalone_occurrence_options(owner_key, series_event_id, occurrences, invited_people, meeting_options, groups=None):
    """Re-apply roles and options to sessions restored on events of their own.

    The people-only counterpart of the standalone half of
    ``apply_teams_occurrence_shifts``: the same onlineMeeting options, and
    nothing else. It never reads or writes a date, never moves an event and
    never creates one -- a people-only save must leave the schedule exactly as
    Microsoft holds it. Returns ``(warnings, details)`` in that function's shape.
    ``groups`` is the option groups this save changed; empty sends nothing.
    """
    warnings, details = [], []
    if groups is not None and not groups:
        return warnings, details
    series_event_id = clean_str(series_event_id)
    for row in occurrences or []:
        standalone_id = clean_str(row.get('graph_event_id'))
        if not standalone_id or standalone_id == series_event_id:
            continue
        if clean_str(row.get('status')).lower() in ('cancelled', 'canceled', 'superseded'):
            continue
        event = {'id': standalone_id, 'onlineMeeting': {'joinUrl': clean_str(row.get('join_url'))}}
        detail = teams_standalone_occurrence_meeting(
            owner_key, event, {'session_number': row.get('session_number')}, invited_people, meeting_options,
            groups=groups,
        )
        warnings.extend(detail.pop('warnings'))
        if not detail.get('online_meeting_id'):
            detail['online_meeting_id'] = clean_str(row.get('online_meeting_id'))
        details.append(detail)
    return warnings, details
def persist_recreated_occurrence_details(live_session_id, recreated_details):
    """Point a moved session at the event and meeting Teams actually gave it.

    A recreated occurrence is its own event with its own Teams link and its own
    online meeting, so the series link and meeting ID are the wrong answer for
    it: learners would join a session that no longer exists, and its transcript,
    recording and attendance would be looked for under a meeting that never ran.
    """
    if not recreated_details:
        return
    now = datetime.utcnow()
    for detail in recreated_details:
        try:
            session_number = int(detail.get('session_number') or 0)
        except (TypeError, ValueError):
            continue
        if session_number <= 0:
            continue
        update = {}
        for column in ('graph_event_id', 'join_url', 'online_meeting_id'):
            value = clean_str(detail.get(column))
            if value:
                update[column] = value
        if not update:
            continue
        update['updated_at'] = now
        update_authoring_rows(
            LIVE_SESSION_OCCURRENCES_TABLE,
            'live_session_id = %s and session_number = %s',
            [live_session_id, session_number],
            update,
        )
def closest_live_occurrence(occurrences, timestamp):
    if not occurrences or not timestamp:
        return None
    comparable_timestamp = timestamp.replace(tzinfo=None)

    def distance(row):
        scheduled = row.get('scheduled_start') or timestamp
        return abs((scheduled.replace(tzinfo=None) - comparable_timestamp).total_seconds())

    return min(
        occurrences,
        key=distance,
    )
def live_session_join_launches(occurrences):
    occurrence_ids = [clean_str(row.get('id')) for row in occurrences if clean_str(row.get('id'))]
    if not occurrence_ids:
        return []
    placeholders = ', '.join(['%s'] * len(occurrence_ids))
    return authoring_fetch_all(
        LIVE_SESSION_JOIN_LAUNCHES_TABLE,
        f'occurrence_id in ({placeholders})',
        occurrence_ids,
        'launched_at asc',
    )
def launch_linked_live_occurrence(occurrences, timestamp, launches, report_id=''):
    """Resolve a Graph run to the Week whose Join button opened it.

    Graph reports identify the online meeting and run time, but not the calendar
    occurrence. The LMS redirect records that missing context. Existing report
    bindings win on re-sync; a launch within 24 hours wins for a new run; the
    scheduled-date heuristic remains only for historical runs with no launch log.
    """
    if not occurrences or not timestamp:
        return None, None
    if report_id:
        stored = next((row for row in occurrences if clean_str(row.get('attendance_report_id')) == clean_str(report_id)), None)
        if stored:
            return stored, None
    by_id = {clean_str(row.get('id')): row for row in occurrences}
    report_id = clean_str(report_id)
    if report_id:
        exact = next(
            (row for row in launches if clean_str(row.get('attendance_report_id')) == report_id),
            None,
        )
        occurrence = by_id.get(clean_str((exact or {}).get('occurrence_id')))
        if occurrence:
            return occurrence, exact

    moment = timestamp.replace(tzinfo=None)
    candidates = []
    for launch in launches:
        bound_report_id = clean_str(launch.get('attendance_report_id'))
        if report_id and bound_report_id and bound_report_id != report_id:
            # A click that has already been matched to one Teams run must not
            # be reused by a later report from the same shared meeting URL.
            continue
        occurrence = by_id.get(clean_str(launch.get('occurrence_id')))
        launched_at = parse_graph_datetime(launch.get('launched_at'))
        if not occurrence or not launched_at:
            continue
        delta = (moment - launched_at.replace(tzinfo=None)).total_seconds()
        # A browser normally opens Teams just before the report starts. Allow a
        # small clock/order skew and long teaching sessions, without letting an
        # old test click steal a later week's real report.
        if -900 <= delta <= 86400:
            candidates.append((abs(delta), launch, occurrence))
    if candidates:
        _distance, launch, occurrence = min(candidates, key=lambda item: item[0])
        return occurrence, launch
    return closest_live_occurrence(occurrences, timestamp), None
def graph_item_with_occurrence_link(item, occurrence, launch=None):
    """Persist the calendar/LMS occurrence chosen for a Graph report or artifact."""
    linked = dict(item) if isinstance(item, dict) else {}
    linked['lmsOccurrenceId'] = clean_str(occurrence.get('id'))
    linked['lmsSessionNumber'] = parse_int(occurrence.get('session_number'), 0)
    linked['calendarEventId'] = clean_str(occurrence.get('graph_event_id'))
    linked['joinLaunchId'] = clean_str((launch or {}).get('id'))
    return linked
def attendance_identity(record):
    identity = record.get('identity') if isinstance(record.get('identity'), dict) else {}
    for key in ('user', 'guest', 'phone', 'encrypted'):
        value = identity.get(key)
        if isinstance(value, dict):
            display_name = clean_str(value.get('displayName') or value.get('name'))
            identity_id = clean_str(value.get('id'))
            if display_name or identity_id:
                return display_name, identity_id
    return '', ''
def attendance_display_name(record):
    if not isinstance(record, dict):
        return ''
    display_name, _identity_id = attendance_identity(record)
    if display_name:
        return display_name
    for key in ('displayName', 'participantDisplayName', 'name'):
        display_name = clean_str(record.get(key))
        if display_name:
            return display_name
    email = clean_str(record.get('emailAddress') or record.get('email')).lower()
    if email and '@' in email:
        local = email.split('@', 1)[0]
        return ' '.join(part.capitalize() for part in re.split(r'[._-]+', local) if part)
    return ''
def merge_attendance_intervals(*interval_groups):
    """Keep every distinct join/leave visit returned across Graph reports."""
    merged = []
    seen = set()
    for intervals in interval_groups:
        for interval in intervals if isinstance(intervals, list) else []:
            if not isinstance(interval, dict):
                continue
            key = (
                clean_str(interval.get('joinDateTime')),
                clean_str(interval.get('leaveDateTime')),
            )
            if key == ('', ''):
                key = (json.dumps(interval, sort_keys=True, default=str), '')
            if key in seen:
                continue
            seen.add(key)
            merged.append(interval)
    merged.sort(key=lambda item: clean_str(item.get('joinDateTime')))
    return merged
def attendance_roster(series, actual_rows, include_absent=False):
    """Merge the invitation roster with Graph attendance for UI/reporting."""
    expected_roles = {}
    organizer = clean_str(series.get('organizer_email')).lower()
    if organizer:
        expected_roles[organizer] = 'Organizer'
    for email in teams_series_email_list(series.get('attendees')):
        expected_roles.setdefault(email, 'Attendee')
    for email in teams_series_email_list(series.get('presenters')):
        expected_roles[email] = 'Presenter'
    for email in teams_series_email_list(series.get('co_organizers')):
        expected_roles[email] = 'Co-organizer'

    rows = []
    actual_emails = set()
    for row in actual_rows:
        email = clean_str(row.get('email')).lower()
        if email:
            actual_emails.add(email)
        intervals = row.get('intervals') if isinstance(row.get('intervals'), list) else []
        row['attended'] = int(row.get('total_attendance_seconds') or 0) > 180
        row['expected'] = bool(email and email in expected_roles)
        row['join_count'] = len(intervals)
        rows.append(row)

    for email, role in expected_roles.items() if include_absent else []:
        if email in actual_emails:
            continue
        rows.append({
            'id': 'EXPECTED-' + hashlib.sha256(email.encode('utf-8')).hexdigest()[:24].upper(),
            'occurrence_id': '',
            'graph_record_id': '',
            'email': email,
            'display_name': attendance_display_name({'emailAddress': email}),
            'role': role,
            'total_attendance_seconds': 0,
            'intervals': [],
            'raw_data': {},
            'attended': False,
            'expected': True,
            'join_count': 0,
        })

    rows.sort(key=lambda row: (
        not bool(row.get('expected')),
        not bool(row.get('attended')),
        clean_str(row.get('display_name') or row.get('email')).lower(),
    ))
    return rows
def attendance_report_rosters(series, actual_rows, include_absent=False):
    """Return one complete expected-vs-attended roster per Graph meeting run.

    A recurring Teams link can be opened on different days. Microsoft publishes
    one attendance report per run and can reuse the same attendee record id in
    those reports, so collapsing rows by attendee would incorrectly turn two
    different days into two rejoins in one session.
    """
    groups = {}
    for source_row in actual_rows:
        row = dict(source_row)
        raw = row.get('raw_data') if isinstance(row.get('raw_data'), dict) else {}
        source_report_ids = raw.get('sourceAttendanceReportIds')
        report_id = clean_str(raw.get('attendanceReportId'))
        if not report_id and isinstance(source_report_ids, list) and len(source_report_ids) == 1:
            report_id = clean_str(source_report_ids[0])
        report_start = clean_str(raw.get('attendanceReportStart'))
        report_end = clean_str(raw.get('attendanceReportEnd'))
        group_key = report_id or report_start or 'legacy'
        group = groups.setdefault(group_key, {
            'report_id': report_id,
            'report_start': report_start,
            'report_end': report_end,
            'rows': [],
        })
        group['rows'].append(row)

    flattened = []
    ordered_groups = sorted(
        groups.values(),
        key=lambda group: group.get('report_start') or '',
        reverse=True,
    )
    for group in ordered_groups:
        report_key = group.get('report_id') or group.get('report_start') or 'legacy'
        roster = attendance_roster(series, group['rows'], include_absent=include_absent)
        for row in roster:
            if row.get('attended') is False:
                row['id'] = f"{row['id']}-{hashlib.sha256(report_key.encode('utf-8')).hexdigest()[:12].upper()}"
            row['attendance_report_id'] = group.get('report_id') or ''
            row['attendance_report_start'] = group.get('report_start') or ''
            row['attendance_report_end'] = group.get('report_end') or ''
            flattened.append(row)
    return flattened
def upsert_live_session_artifact(occurrence, artifact_type, artifact):
    graph_id = clean_str(artifact.get('id'))
    if not graph_id:
        return False
    # Deterministic, not uuid4(): the upsert key below (occurrence_id +
    # artifact_type + graph_artifact_id) already recognises a re-synced
    # artifact as the same row, but a random id here still overwrote its own
    # primary key on every sync -- so a link or an open preview holding
    # yesterday's id 404'd the moment someone re-fetched attendance, even
    # though the underlying Teams artifact never changed. Hashing the same
    # key this row is matched on gives it one id for life.
    artifact_id = 'ART-' + hashlib.sha256(
        f"{occurrence['id']}|{artifact_type}|{graph_id}".encode('utf-8')
    ).hexdigest()[:32].upper()
    payload = {
        'id': artifact_id,
        'occurrence_id': occurrence['id'],
        'artifact_type': artifact_type,
        'graph_artifact_id': graph_id,
        'call_id': clean_str(artifact.get('callId')),
        'content_correlation_id': clean_str(artifact.get('contentCorrelationId')),
        'content_url': clean_str(
            artifact.get('transcriptContentUrl') if artifact_type == 'transcript'
            else artifact.get('recordingContentUrl')
        ),
        'created_datetime': parse_graph_datetime(artifact.get('createdDateTime')),
        'end_datetime': parse_graph_datetime(artifact.get('endDateTime')),
        'metadata': json_db_value(artifact),
    }
    # Serialize against staff hide/restore. Graph refreshes must not overwrite
    # LMS visibility, including a toggle committed while discovery was running.
    with transaction.atomic(), connection.cursor() as cursor:
        lock = ' FOR UPDATE' if connection.vendor == 'postgresql' else ''
        if lock:
            # Two syncs of one meeting (a retry overlapping a worker) both find
            # no row for a new id and would both insert. One session's artifacts
            # of one type are written one at a time; the lock ends with the transaction.
            cursor.execute('SELECT pg_advisory_xact_lock(hashtext(%s))',
                           [f"live-session-artifact|{occurrence['id']}|{artifact_type}"])
        cursor.execute(f'SELECT metadata FROM {authoring_table_name(LIVE_SESSION_ARTIFACTS_TABLE)} '
                       'WHERE occurrence_id=%s AND artifact_type=%s AND graph_artifact_id=%s' + lock,
                       [occurrence['id'], artifact_type, graph_id])
        existing = cursor.fetchone()
        metadata = dict(artifact)
        metadata.pop('lmsHiddenFromLearners', None)
        metadata.pop('lmsTranscriptTimeline', None)
        metadata.pop('lmsBunnyRecording', None)
        same_recording = None if existing else _same_artifact_under_new_graph_id(cursor, lock, payload)
        if same_recording:
            # Teams re-issued the id of an artifact already saved (same call and
            # recording window). Keep the one LMS row -- its id, archive, visibility
            # and transcript timing -- and only move it to the current Graph id.
            row_id, saved = same_recording
            saved_metadata = parse_json_value(saved, {})
            metadata['lmsHiddenFromLearners'] = saved_metadata.get('lmsHiddenFromLearners') is True
            if 'lmsTranscriptTimeline' in saved_metadata:
                metadata['lmsTranscriptTimeline'] = saved_metadata['lmsTranscriptTimeline']
            if 'lmsBunnyRecording' in saved_metadata:
                metadata['lmsBunnyRecording'] = saved_metadata['lmsBunnyRecording']
            cursor.execute(
                f'UPDATE {authoring_table_name(LIVE_SESSION_ARTIFACTS_TABLE)} SET graph_artifact_id=%s, content_url=%s, '
                'content_correlation_id=%s, metadata=%s, updated_at=%s WHERE id=%s',
                [graph_id, payload['content_url'], payload['content_correlation_id'], json_db_value(metadata),
                 datetime.utcnow(), row_id],
            )
            return True
        if existing:
            saved_metadata = parse_json_value(existing[0], {})
            metadata['lmsHiddenFromLearners'] = saved_metadata.get('lmsHiddenFromLearners') is True
            if 'lmsTranscriptTimeline' in saved_metadata:
                metadata['lmsTranscriptTimeline'] = saved_metadata['lmsTranscriptTimeline']
            if 'lmsBunnyRecording' in saved_metadata:
                metadata['lmsBunnyRecording'] = saved_metadata['lmsBunnyRecording']
        payload['metadata'] = json_db_value(metadata)
        authoring_upsert(LIVE_SESSION_ARTIFACTS_TABLE, ['occurrence_id', 'artifact_type', 'graph_artifact_id'], payload)
    return True
def _same_artifact_under_new_graph_id(cursor, lock, payload):
    """(row id, metadata) of this occurrence's artifact for the same call and recording window.

    Graph has returned one recording under a second id on a later sync, and two
    ids for one recording in the same listing; matching only on
    graph_artifact_id then saved and archived it twice. Microsoft's content
    correlation id names the recording itself (one per recording, shared by no
    other in production), so it matches even when the timing is reported with a
    different precision -- but never across calls, which keeps two recordings of
    one session apart.
    """
    table = authoring_table_name(LIVE_SESSION_ARTIFACTS_TABLE)
    correlation = clean_str(payload.get('content_correlation_id'))
    if correlation:
        cursor.execute(
            f'SELECT id, metadata FROM {table} WHERE occurrence_id=%s AND artifact_type=%s '
            "AND content_correlation_id=%s AND (call_id=%s OR call_id='' OR call_id IS NULL OR %s='') "
            'ORDER BY created_at LIMIT 1' + lock,
            [payload['occurrence_id'], payload['artifact_type'], correlation, payload['call_id'], payload['call_id']],
        )
        row = cursor.fetchone()
        if row:
            return row
    if not payload['call_id'] or not payload['created_datetime']:
        return None
    cursor.execute(
        f'SELECT id, metadata FROM {table} '
        'WHERE occurrence_id=%s AND artifact_type=%s AND call_id=%s AND created_datetime=%s '
        'AND end_datetime IS NOT DISTINCT FROM %s ORDER BY created_at LIMIT 1' + lock,
        [payload['occurrence_id'], payload['artifact_type'], payload['call_id'],
         payload['created_datetime'], payload['end_datetime']],
    )
    return cursor.fetchone()
def remove_artifact_from_wrong_occurrences(occurrences, target_occurrence, artifact_type, artifact):
    """Remove an earlier date-heuristic copy when launch tracking remaps an artifact."""
    graph_id = clean_str(artifact.get('id'))
    target_id = clean_str(target_occurrence.get('id'))
    occurrence_ids = {clean_str(row.get('id')) for row in occurrences}
    if not graph_id or not target_id:
        return
    matches = authoring_fetch_all(
        LIVE_SESSION_ARTIFACTS_TABLE,
        'artifact_type = %s and graph_artifact_id = %s',
        [artifact_type, graph_id],
    )
    for row in matches:
        occurrence_id = clean_str(row.get('occurrence_id'))
        if occurrence_id in occurrence_ids and occurrence_id != target_id:
            authoring_delete(LIVE_SESSION_ARTIFACTS_TABLE, 'id = %s', [row['id']])
@csrf_exempt
def stored_leftover_slots(live_session_id):
    """Teams slots outside the module plan, as the last calendar status check found them.

    Read from the status sweep's own snapshot, never from Microsoft here. Empty
    when status sync is not provisioned or has not run: a missing reading is
    not evidence of anything.
    """
    try:
        with connection.cursor() as cursor:
            cursor.execute("SELECT to_regclass('curriculum.teams_calendar_sync_state')")
            if not cursor.fetchone()[0]:
                return []
            cursor.execute('SELECT snapshot FROM curriculum.teams_calendar_sync_state WHERE live_session_id = %s',
                           [live_session_id])
            row = cursor.fetchone()
    except Exception:
        logger.exception('Teams leftover slots could not be read.')
        return []
    snapshot = parse_json_value(row[0], {}) if row else {}
    leftovers = (snapshot or {}).get('leftovers') if isinstance(snapshot, dict) else None
    return leftovers if isinstance(leftovers, list) else []
@require_GET
def curriculum_teams_meeting_artifact_content(request, live_session_id, artifact_id):
